// Saved models keep their original local frame (X=width, Y=height, Z=depth).
// This proper rotation presents that geometry in the shared semantic frame:
// X=width, Y=length, Z=height. The X sign is reversed to preserve handedness.
const legacyPartToSemantic = new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(
  new THREE.Vector3(-1, 0, 0), new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 1, 0)
));
const semanticAxisToLegacy = { x: 'x', y: 'z', z: 'y' };
function legacyAxisDirectionToSemantic(value) {
  const match = /^([+-])([xyz])$/.exec(String(value || ''));
  if (!match) return value;
  const sign = match[1] === '+' ? 1 : -1;
  const vector = new THREE.Vector3(match[2] === 'x' ? sign : 0, match[2] === 'y' ? sign : 0, match[2] === 'z' ? sign : 0).applyQuaternion(legacyPartToSemantic);
  const axis = ['x', 'y', 'z'].find(key => Math.abs(vector[key]) > .5);
  return `${vector[axis] < 0 ? '-' : '+'}${axis}`;
}
function semanticAxisDirectionToLegacy(value) {
  const match = /^([+-])([xyz])$/.exec(String(value || ''));
  if (!match) return value;
  const sign = match[1] === '+' ? 1 : -1;
  const vector = new THREE.Vector3(match[2] === 'x' ? sign : 0, match[2] === 'y' ? sign : 0, match[2] === 'z' ? sign : 0).applyQuaternion(legacyPartToSemantic.clone().invert());
  const axis = ['x', 'y', 'z'].find(key => Math.abs(vector[key]) > .5);
  return `${vector[axis] < 0 ? '-' : '+'}${axis}`;
}
