const axisOffsetDialog=document.createElement('dialog');axisOffsetDialog.className='axis-offset-dialog';axisOffsetDialog.innerHTML='<form method="dialog"><h3>轴向偏移</h3><p id="axisOffsetLabel"></p><label>偏移尺寸 / mm<input id="axisOffsetValue" type="number" step="0.1" value="0"></label><div><button value="cancel">取消</button><button id="applyAxisOffset" type="button" class="primary">应用</button></div></form>';document.body.appendChild(axisOffsetDialog);
function applyAxisOffset(){if(!selectedMeshes.length)return;const axis=axisOffsetDialog.dataset.axis,raw=String($('axisOffsetValue').value).trim(),value=Number(raw);if(!axis||raw===''||!Number.isFinite(value)){$('status').textContent='轴向偏移必须是有限数值；未修改模型。';return false}snapshot();if(selectionPivot)prepareGroupTransform();const object=selectionPivot||selectedMesh;if(selectionPivot)object.position[axis]+=value/1000;else{const delta=new THREE.Vector3(axis==='x'?1:0,axis==='y'?1:0,axis==='z'?1:0).multiplyScalar(value/1000);if(transformFrame==='local'&&selectedMesh.userData.workFrame){const frame=activeFrameWorld(),world=object.getWorldPosition(new THREE.Vector3()).add(delta.applyQuaternion(frame.quaternion));model.updateWorldMatrix(true,false);object.position.copy(model.worldToLocal(world))}else object.position.add(delta.applyQuaternion(legacyPartToSemantic.clone().invert()))}if(selectionPivot)applyGroupTransformDelta();groupTransformStart=null;selectionHelpers.forEach(helper=>helper.update());captureCustomScene();syncTransformFields();axisOffsetDialog.close();markDirty();$('status').textContent=`已沿 ${axis.toUpperCase()} 轴偏移 ${value.toFixed(1)} mm。`;return true}
