function openAxisOffsetDialog(axis){const normalized=String(axis||'').toLowerCase();if(!selectedMeshes.length||!['x','y','z'].includes(normalized))return;axisOffsetDialog.dataset.axis=normalized;axisOffsetDialog.querySelector('#axisOffsetLabel').textContent=`当前语义轴：${normalized.toUpperCase()}（${normalized==="x"?"宽度":normalized==="y"?"长度":"高度"}）；正值向正方向偏移，负值向反方向偏移。`;axisOffsetDialog.querySelector('#axisOffsetValue').value='0.0';if(!axisOffsetDialog.open)axisOffsetDialog.showModal();axisOffsetDialog.querySelector('#axisOffsetValue').focus();axisOffsetDialog.querySelector('#axisOffsetValue').select()}
function axisFromObject(object){let current=object;while(current){const material=current.material;const color=material?.color;if(color){const r=color.r,g=color.g,b=color.b,max=Math.max(r,g,b),min=Math.min(r,g,b);if(max>0.45&&max-min>0.18){if(r===max&&r>g*1.18&&r>b*1.18)return 'X';if(g===max&&g>r*1.18&&g>b*1.18)return 'Y';if(b===max&&b>r*1.18&&b>g*1.18)return 'Z'}}const name=String(current.name||'').trim().toUpperCase();if(name==='X'||name==='Y'||name==='Z')return name;if(name&&/^(XY|YZ|XZ|XYZ)$/.test(name))return '';if(name)return '';current=current.parent}return ''}
function showAxisHint(axis,event){if(!axis){axisHint.hidden=true;return}axisHint.textContent=`${axis} 轴 · ${axis==="X"?"宽度":axis==="Y"?"长度":"高度"}`;axisHint.dataset.axis=axis;const rect=viewport.getBoundingClientRect();axisHint.style.left=`${Math.max(8,Math.min(rect.width-52,event.clientX-rect.left+12))}px`;axisHint.style.top=`${Math.max(8,Math.min(rect.height-30,event.clientY-rect.top-24))}px`;axisHint.hidden=false}
renderer.domElement.addEventListener('pointermove',event=>{if(!selectedMeshes.length||!transform.object){axisHint.hidden=true;return}const rect=renderer.domElement.getBoundingClientRect();pointer.x=(event.clientX-rect.left)/rect.width*2-1;pointer.y=-(event.clientY-rect.top)/rect.height*2+1;raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(transform.getHelper().children,true).find(item=>axisFromObject(item.object));const axis=hit?(transform.axis||axisFromObject(hit.object)):'';showAxisHint(axis,event)});
