const mat = {
  galvanized:new THREE.MeshStandardMaterial({color:0xb9c4c7,metalness:.72,roughness:.34}), aluminium:new THREE.MeshStandardMaterial({color:0xdbe2e3,metalness:.8,roughness:.25}),
  dark:new THREE.MeshStandardMaterial({color:0x263137,metalness:.38,roughness:.5}), black:new THREE.MeshStandardMaterial({color:0x11181b,roughness:.55}),
  blue:new THREE.MeshStandardMaterial({color:0x197fa7,metalness:.42,roughness:.32}), copper:new THREE.MeshStandardMaterial({color:0xb86b3d,metalness:.72,roughness:.3}),
  filter:new THREE.MeshStandardMaterial({color:0xf4f0df,roughness:.86,side:THREE.DoubleSide}), actuator:new THREE.MeshStandardMaterial({color:0xcbd0cd,roughness:.5}), red:new THREE.MeshStandardMaterial({color:0xc63b2f,roughness:.5})
};
const mm=v=>(Number(v)||1)/1000;
function materialKey(material){return Object.keys(mat).find(key=>mat[key]===material)||'galvanized'}
function mesh(parent,geometry,material,x=0,y=0,z=0,rx=0,ry=0,rz=0){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=m.receiveShadow=true;m.userData.editable=true;m.userData.materialKey=materialKey(material);m.userData.solidProperty='rigid';parent.add(m);return m}
function box(parent,w,h,d,x=0,y=0,z=0,material=mat.galvanized){return mesh(parent,new THREE.BoxGeometry(w,h,d),material,x,y,z)}
function cyl(parent,r,len,x=0,y=0,z=0,material=mat.galvanized,axis='y'){const m=mesh(parent,new THREE.CylinderGeometry(r,r,len,28),material,x,y,z);if(axis==='x')m.rotation.z=Math.PI/2;if(axis==='z')m.rotation.x=Math.PI/2;return m}
function frame(parent,w,h,d,bar,material=mat.galvanized){box(parent,w,bar,d,0,h/2-bar/2,0,material);box(parent,w,bar,d,0,-h/2+bar/2,0,material);box(parent,bar,h-2*bar,d,w/2-bar/2,0,0,material);box(parent,bar,h-2*bar,d,-w/2+bar/2,0,0,material)}
function torus(parent,r,t,x,y,z,material=mat.copper,rx=0,ry=0,rz=0,arc=Math.PI*2){return mesh(parent,new THREE.TorusGeometry(r,t,10,32,arc),material,x,y,z,rx,ry,rz)}

function buildRectFlange(p,g){const w=mm(p.dimensions.width),h=mm(p.dimensions.height),d=mm(p.dimensions.depth),f=mm(p.params.flange),t=.012;frame(g,w,h,d,t);frame(g,w+f*2,h+f*2,t,f,mat.aluminium);const n=Math.max(2,+p.params.holes||3);for(let i=0;i<n;i++){const x=-w/2+(i+.5)*w/n;for(const y of [-h/2-f/2,h/2+f/2])cyl(g,.009,.004,x,y,d/2+t,mat.dark,'z')}for(let i=0;i<n;i++){const y=-h/2+(i+.5)*h/n;for(const x of [-w/2-f/2,w/2+f/2])cyl(g,.009,.004,x,y,d/2+t,mat.dark,'z')}}
function buildRoundFlange(p,g){const r=mm(p.dimensions.diameter)/2,d=mm(p.dimensions.depth),f=mm(p.params.flange);cyl(g,r,d,0,0,0,mat.galvanized,'z');torus(g,r+f*.45,f*.45,0,0,d/2,mat.aluminium);const n=+p.params.holes||8;for(let i=0;i<n;i++){const a=i*Math.PI*2/n;cyl(g,.009,.006,Math.cos(a)*(r+f*.45),Math.sin(a)*(r+f*.45),d/2+.008,mat.dark,'z')}}
function buildDamper(p,g){const w=mm(p.dimensions.width),h=mm(p.dimensions.height),d=mm(p.dimensions.depth),count=Math.max(2,+p.params.blades||7),angle=THREE.MathUtils.degToRad(+p.params.angle||0);frame(g,w,h,d,.055);for(let i=0;i<count;i++){const y=-h*.39+i*h*.78/(count-1);const blade=box(g,w*.86,.025,d*.6,0,y,0,mat.aluminium);blade.rotation.x=(p.params.mode==='opposed'&&i%2?-1:1)*angle;cyl(g,.012,w*.92,0,y,d*.32,mat.dark,'x')}const bracket=box(g,.28,.025,.22,w*.18,h/2+.05,0,mat.galvanized);bracket.rotation.z=.02;const a=clone(p);a.dimensions={width:240,height:170,depth:105};buildActuator(a,g,new THREE.Vector3(w*.18,h/2+.16,.03))}
function buildActuator(p,g,offset=new THREE.Vector3()){const w=mm(p.dimensions.width),h=mm(p.dimensions.height),d=mm(p.dimensions.depth);const q=new THREE.Group();q.position.copy(offset);g.add(q);box(q,w,h,d,0,0,0,mat.actuator);cyl(q,h*.28,.025,-w*.18,0,d/2+.015,mat.black,'z');box(q,mm(p.params.shaft||14),mm(p.params.shaft||14),d*.55,-w*.18,0,d*.72,mat.galvanized);box(q,w*.35,.025,.045,w*.18,h/2+.02,d*.2,mat.red);for(const x of [-w*.36,w*.36])cyl(q,.009,.008,x,-h*.34,d/2+.01,mat.dark,'z')}
function fanWheel(g,r,depth,blades,style){cyl(g,r*.16,depth,0,0,0,mat.dark,'z');torus(g,r*.82,.035,0,0,depth/2,mat.aluminium);for(let i=0;i<blades;i++){const a=i*Math.PI*2/blades;const b=box(g,r*.58,r*.15,depth*.72,Math.cos(a)*r*.48,Math.sin(a)*r*.48,0,mat.aluminium);b.rotation.z=a+(style==='forward'?.58:-.4)}}
function buildCentrifugal(p,g){
  const w=mm(p.dimensions.width),h=mm(p.dimensions.height),d=mm(p.dimensions.depth),caseW=w*.86,caseH=h*.78,caseD=d*.64;
  const r=Math.min(caseW,caseH)*.39, sideT=Math.max(.018,d*.035);
  // 分体蜗壳：两块侧板、弧形主体、上部出风箱，保留真实风机的开口层次。
  cyl(g,r,sideT,0,0,-caseD/2-sideT/2,mat.galvanized,'z');
  cyl(g,r,sideT,0,0,caseD/2+sideT/2,mat.galvanized,'z');
  box(g,caseW*.72,.06,caseD,-caseW*.12,-caseH*.36,0,mat.galvanized);
  box(g,.06,caseH*.72,caseD,-caseW*.42,0,0,mat.galvanized);
  box(g,caseW*.45,.06,caseD,caseW*.18,caseH*.27,0,mat.galvanized);
  box(g,.06,caseH*.35,caseD,caseW*.38,caseH*.12,0,mat.galvanized);
  // 蜗壳外圈与出风口法兰。
  torus(g,r*.88,.035,0,0,0,mat.aluminium,Math.PI/2,0,0);
  box(g,caseW*.28,caseH*.18,caseD*.9,caseW*.31,caseH*.41,0,mat.galvanized);
  frame(g,caseW*.28,caseH*.18,caseD*.94,.025,mat.aluminium);
  // 叶轮、中心轮毂和入口锥体。
  cyl(g,r*.18,caseD*.52,0,0,-caseD*.05,mat.dark,'z');
  fanWheel(g,r*.76,caseD*.58,+p.params.blades||10,p.params.style);
  const inlet=new THREE.CylinderGeometry(r*.54,r*.25,caseD*.22,32);
  mesh(g,inlet,mat.aluminium,0,0,-caseD*.45,Math.PI/2,0,0);
  // 侧向电机、方轴和滑轨底座。
  cyl(g,d*.13,d*.5,caseW*.46,-caseH*.06,0,mat.dark,'x');
  cyl(g,d*.075,d*.58,caseW*.66,-caseH*.06,0,mat.aluminium,'x');
  box(g,caseW*.96,.07,caseD*.9,0,-caseH*.51,0,mat.dark);
  box(g,.08,caseH*.18,.08,-caseW*.35,-caseH*.42,0,mat.aluminium);
  box(g,.08,caseH*.18,.08,caseW*.35,-caseH*.42,0,mat.aluminium);
}
function buildPlugFan(p,g){const r=mm(p.dimensions.diameter)/2,d=mm(p.dimensions.depth);torus(g,r*.92,.06,0,0,d*.12,mat.galvanized);fanWheel(g,r*.78,d*.22,+p.params.blades||7,'backward');cyl(g,r*.18,d*.48,0,0,-d*.25,mat.dark,'z');for(let i=0;i<4;i++){const a=i*Math.PI/2;const arm=box(g,r*.8,.045,.055,Math.cos(a)*r*.4,Math.sin(a)*r*.4,-d*.18,mat.galvanized);arm.rotation.z=a}}
function buildAxialFan(p,g){const r=mm(p.dimensions.diameter)/2,d=mm(p.dimensions.depth);cyl(g,r,d,0,0,0,mat.galvanized,'z');cyl(g,r*.88,d*1.03,0,0,0,mat.black,'z');cyl(g,r*.2,d*.72,0,0,0,mat.dark,'z');const n=+p.params.blades||6;for(let i=0;i<n;i++){const a=i*Math.PI*2/n;const blade=box(g,r*.58,r*.19,.035,Math.cos(a)*r*.42,Math.sin(a)*r*.42,d*.52,mat.aluminium);blade.rotation.z=a+.35}}
function buildCoil(p,g){const w=mm(p.dimensions.width),h=mm(p.dimensions.height),d=mm(p.dimensions.depth),rows=Math.max(2,+p.params.rows||4),circuits=Math.max(4,+p.params.circuits||10);frame(g,w,h,d,.055);box(g,w*.86,h*.84,d*.58,0,0,0,p.params.mode==='heating'?mat.copper:mat.blue);for(let i=0;i<26;i++)box(g,w*.83,.005,d*.61,0,-h*.4+i*h*.8/25,d*.01,mat.aluminium);for(let row=0;row<rows;row++)for(let i=0;i<circuits;i++){const y=-h*.36+i*h*.72/(circuits-1),z=-d*.25+row*d*.5/(rows-1);torus(g,.035,.009,-w*.46,y,z,mat.copper,0,Math.PI/2,0,Math.PI)}for(const x of [w*.43,w*.49])cyl(g,.035,h*.72,x,0,-d*.2,mat.galvanized);const pr=mm(p.params.pipeDiameter||50)/2;for(const y of [h*.27,-h*.27])cyl(g,pr,w*.32,w*.58,y,-d*.2,mat.galvanized,'x')}
function buildPanelFilter(p,g){const w=mm(p.dimensions.width),h=mm(p.dimensions.height),d=mm(p.dimensions.depth);frame(g,w,h,d,.035);const n=Math.max(6,+p.params.pleats||18);for(let i=0;i<n;i++){const x=-w*.42+i*w*.84/(n-1);const strip=box(g,.012,h*.84,d*.82,x,0,0,mat.filter);strip.rotation.y=(i%2?.26:-.26)}}
function buildBagFilter(p,g){const w=mm(p.dimensions.width),h=mm(p.dimensions.height),d=mm(p.dimensions.depth),n=Math.max(2,+p.params.bags||6);frame(g,w,h,.06,.035);for(let i=0;i<n;i++){const x=-w*.4+(i+.5)*w*.8/n;const bag=box(g,w*.72/n,h*.72,d*.88,x,0,-d*.47,mat.filter);bag.geometry.translate(0,0,-d*.44);bag.geometry.userData.geometryDirty=true;box(g,.025,h*.78,.055,-w*.4+i*w*.8/n,0,0,mat.galvanized)}}
function buildCompact(p,g){const w=mm(p.dimensions.width),h=mm(p.dimensions.height),d=mm(p.dimensions.depth),n=Math.max(2,+p.params.columns||4);frame(g,w,h,d,.055,mat.black);for(let i=0;i<n;i++){const x=-w*.4+(i+.5)*w*.8/n;box(g,w*.7/n,h*.78,d*.82,x,0,0,mat.filter);box(g,.045,h*.82,d*.9,-w*.4+i*w*.8/n,0,0,mat.black);for(let j=0;j<24;j++)box(g,w*.62/n,.004,d*.84,x,-h*.36+j*h*.72/23,d*.01,mat.dark)}}

const builders={rectFlange:buildRectFlange,roundFlange:buildRoundFlange,damper:buildDamper,actuator:buildActuator,centrifugal:buildCentrifugal,plugFan:buildPlugFan,axialFan:buildAxialFan,coil:buildCoil,panelFilter:buildPanelFilter,bagFilter:buildBagFilter,compactFilter:buildCompact};
function loadLibrary(){const saved=STORE?.loadSync?.();if(saved?.length)return saved.map((part,index)=>STORE.normalizePart(part,index));return clone(DB.parts).map((part,index)=>STORE?.normalizePart?.(part,index)||DB.normalizePart(part))}
function persist(){try{library=STORE?.save?.(library)||library;const state=STORE?.sharedState?.();if(state?.exists){$('saveState').textContent='本机已保存 · 正在同步共享库';STORE.saveShared(library,customCategories).then(()=>{$('saveState').textContent='本机与共享库均已保存';$('status').textContent=`${activePart.name} 已同步到共享库，整机可按 ${activePart.id} 调用。`}).catch(error=>{$('saveState').textContent='仅本机已保存 · 共享同步失败';$('status').textContent=`共享同步失败：${error.message} 本机版本仍已保留，请读取共享版本后再处理。`})}else{$('saveState').textContent='已保存到本机 · 尚未发布共享';$('status').textContent=`已保存 ${activePart.name} 到本机；共享库尚未建立。`}return true}catch(error){$('saveState').textContent='保存失败';$('status').textContent=error.message||'零件库保存失败，请先导出 JSON 备份。';return false}}
function saveDraft(){if(!hasUnsavedChanges){clearDraft();return}if(!activePart||!model||!Array.isArray(activePart.customScene))return;try{model.updateMatrixWorld(true);captureCustomScene();localStorage.setItem(draftStorageKey,JSON.stringify({part:activePart,updatedAt:new Date().toISOString()}))}catch(error){console.warn('保存临时编辑草稿失败',error)}}
function loadDraft(partId){try{const draft=JSON.parse(localStorage.getItem(draftStorageKey)||'null');return draft?.part?.id===partId?draft.part:null}catch{return null}}
function clearDraft(){try{localStorage.removeItem(draftStorageKey)}catch{}}
