function intersectBox(a,b){const min=new THREE.Vector3(Math.max(a.min.x,b.min.x),Math.max(a.min.y,b.min.y),Math.max(a.min.z,b.min.z)),max=new THREE.Vector3(Math.min(a.max.x,b.max.x),Math.min(a.max.y,b.max.y),Math.min(a.max.z,b.max.z));return max.x-min.x>1e-5&&max.y-min.y>1e-5&&max.z-min.z>1e-5?new THREE.Box3(min,max):null}
