function splitSelectedDisconnected(){const targets=expandGrouped(selectedMeshes).filter(item=>item?.isMesh&&item.parent===model),plans=targets.map(target=>({target,parts:splitDisconnectedGeometry(target.geometry)})).filter(plan=>plan.parts.length>1);if(!plans.length){$('status').textContent='当前选择没有互不相连的实体部分。';return}snapshot();const created=[];for(const {target,parts} of plans){const original=target.geometry;target.geometry=parts[0];target.userData.groupId='';target.name=`${target.name} · 分割 1`;target.material.side=THREE.DoubleSide;target.material.needsUpdate=true;created.push(target);for(let index=1;index<parts.length;index++)created.push(createSplitPart(target,parts[index],index));original.dispose()}clearSelection();captureCustomScene();refreshMeshList();selectMeshes(created.length?[created[0]]:[]);markDirty();$('status').textContent=`已拆分为 ${created.length} 个独立构件，当前只选中“${created[0]?.name||'分割 1'}”；点击其他部分或在构件列表中选择后，可单独删除。`}
function cutPlasticWithRigid(){
  const selection=expandGrouped(selectedMeshes).filter(item=>item?.isMesh&&item.parent===model);
  const plastics=selection.filter(item=>item.userData.solidProperty==='plastic');
  const rigids=selection.filter(item=>item.userData.solidProperty!=='plastic');
  if(!plastics.length||!rigids.length){$('status').textContent='切割需要同时选中至少一个“可塑”构件和一个“刚性”构件。';return}
  const groupProperties=new Map();
  for(const item of selection){if(!item.userData.groupId)continue;const values=groupProperties.get(item.userData.groupId)||new Set();values.add(item.userData.solidProperty==='plastic'?'plastic':'rigid');groupProperties.set(item.userData.groupId,values)}
  if([...groupProperties.values()].some(values=>values.size>1)){$('status').textContent='同一组合内不能同时包含刚性和可塑构件，请先解除组合或分别选择。';return}
  model.updateMatrixWorld(true);
  const cutters=rigids.map(item=>({item,box:worldBox(item)}));
  const cutterBoxes=cutters.map(cutter=>cutter.box);
  const affected=plastics.filter(target=>{const box=worldBox(target);return cutterBoxes.some(cutter=>intersectBox(box,cutter))});
  if(!affected.length){$('status').textContent='选中的刚性与可塑构件没有重叠，未执行切割。';return}
  const affectedBoxes=affected.map(target=>worldBox(target));
  const consumed=cutters.filter(cutter=>affectedBoxes.some(targetBox=>intersectBox(targetBox,cutter.box))).map(cutter=>cutter.item);
  const keepCutters=$('cutToolPolicy')?.value==='keep';
  snapshot();
  const created=[],removed=[];
  const unaffected=plastics.filter(item=>!affected.includes(item));
  let failed=0;
  for(const target of affected){
    const targetBox=worldBox(target);
    const targetCutters=consumed.filter(cutter=>intersectBox(targetBox,worldBox(cutter)));
    const resultGeometry=subtractMesh(target,targetCutters);
    if(!resultGeometry){failed++;continue}
    const resultParts=splitDisconnectedGeometry(resultGeometry);
    const material=target.material;
    const key=target.userData.materialKey||materialKey(material);
    const targetName=target.name;
    target.geometry.dispose();
    target.geometry=resultParts.shift();
    // CSG creates both exterior and newly exposed pocket faces. Keep the
    // result double-sided so a valid shallow pocket can never look transparent
    // because one clipped polygon inherited the opposite winding.
    target.material.side=THREE.DoubleSide;
    target.material.needsUpdate=true;
    target.userData.materialKey=key;
    target.userData.solidProperty='plastic';
    target.userData.groupId='';
    target.name=targetName;
    created.push(target);
    resultParts.forEach((geometry,index)=>created.push(createSplitPart(target,geometry,index+1)));
  }
  if(!created.length&&!removed.length){undoStack.pop();redoStack=[];$('status').textContent='切割没有生成有效实体，未消耗刀具。';return}
  for(const target of removed){model.remove(target);target.geometry.dispose()}
  if(!keepCutters)for(const cutter of consumed){model.remove(cutter);cutter.geometry.dispose()}
  clearSelection();
  captureCustomScene();
  refreshMeshList();
  selectMeshes(created.length?[created[0]]:unaffected.slice(0,1));
  markDirty();
  $('status').textContent=`切割完成，生成 ${created.length} 个可独立选择和删除的实体部分，${keepCutters?'保留':'消耗'} ${consumed.length} 个切割工具${failed?`，${failed} 个目标未生成有效差集并保留原状`:''}；未相交构件保持原状。`;
}
