function undoOneStep(){const now=performance.now();if(now-lastUndoAt<180)return;lastUndoAt=now;if(!undoStack.length){$('status').textContent='已经是最早一步。';return}const current=serializeScene(),previous=undoStack.pop();if(!previous.length&&current.length){undoStack.push(previous);$('status').textContent='已阻止一次会清空当前场景的回退，请继续操作或使用“恢复默认”。';return}redoStack.push(current);restore(previous);$('status').textContent='已后退一步。'}function redoOneStep(){if(!redoStack.length){$('status').textContent='已经是最新一步。';return}undoStack.push(serializeScene());restore(redoStack.pop());$('status').textContent='已前进一步。'}$('undoBtn').onclick=undoOneStep;$('redoBtn').onclick=redoOneStep;
