$('confirmSave').onclick=()=>{
  const name=$('saveName').value.trim(),modelName=$('saveModel').value.trim(),mode=$('saveMode').value;
  if(!name){$('saveMessage').textContent='请输入图块名称';return}
  if(mode==='blank'){
    const id=STORE?.createId?.('custom')||`custom-${Date.now().toString(36)}`;
    activePart={id,name,model:modelName||'CUSTOM',category:$('saveCategory').value,kind:'custom',description:'用户新建的可编辑图块。',source:'用户手动编辑',dimensions:{width:200,height:200,depth:200},params:{},mounting:{flow:'+z',up:'+y'},customScene:[{id:STORE?.createId?.('component')||'component-1',name:'基础方体',geometry:{type:'box',size:[.2,.2,.2]},material:'galvanized',solidProperty:'rigid',groupId:'',position:[0,0,0],rotation:[0,0,0],scale:[1,1,1]}]};
    library.push(clone(activePart));
  }else{
    model.updateMatrixWorld(true);captureCustomScene();
    if(mode==='new'){
      const copy=clone(activePart);copy.id=STORE?.createId?.('custom')||`custom-${Date.now().toString(36)}`;copy.name=name;copy.model=modelName||'CUSTOM';copy.category=$('saveCategory').value;copy.source='用户手动编辑';library.push(clone(copy));activePart=copy;
    }else{
      activePart.name=name;activePart.model=modelName;activePart.category=$('saveCategory').value;
      const index=library.findIndex(item=>item.id===activePart.id);if(index>=0)library[index]=clone(activePart);else library.push(clone(activePart));
    }
  }
  activeCategory=activePart.category;if(!persist())return;establishSavedBoundary();$('saveDialog').close();
  if(mode==='new'||mode==='blank')selectPart(activePart.id);else{$('viewerTitle').textContent=activePart.name;$('viewerMeta').textContent=activePart.model;$('source').textContent=activePart.source;$('description').textContent=activePart.description;$('partId').textContent=activePart.id;renderCatalog();$('saveState').textContent='已保存到本机';$('status').textContent=`已保存 ${activePart.name}。该保存点已锁定，Ctrl+Z 不会回退到保存前。`}
  $('saveMessage').textContent='';
};
