$('categoryRename').onclick=()=>{const id=$('categoryAssign').value,item=customCategories.find(category=>category.id===id);if(!item){$('status').textContent='系统分类不能改名；请选择自建分类。';return}const name=prompt('请输入新的分类名称',item.name);if(!name?.trim())return;item.name=name.trim();saveCustomCategories();renderCatalog();$('status').textContent=`分类已改名为“${item.name}”。`};
$('categoryDelete').onclick=()=>{const id=$('categoryAssign').value,item=customCategories.find(category=>category.id===id);if(!item){$('status').textContent='系统分类不能删除；请选择自建分类。';return}if(library.some(part=>part.category===id)){$('status').textContent='该分类中仍有零件，请先将零件归入其他分类。';return}if(!confirm(`确定删除分类“${item.name}”吗？`))return;customCategories=customCategories.filter(category=>category.id!==id);saveCustomCategories();activeCategory='all';renderCatalog();$('status').textContent=`已删除分类“${item.name}”。`};
const contextMenu=$('contextMenu');
for(const [action,label] of [['alignX','X 轴线对齐'],['alignY','Y 轴线对齐'],['alignZ','Z 轴线对齐']]){const button=document.createElement('button');button.dataset.context=action;button.textContent=label;contextMenu.appendChild(button)}
function hideContextMenu(){contextMenu.hidden=true}
function showContextMenuAt(clientX,clientY){if(!selectedMeshes.length)return;contextMenu.style.left=`${Math.min(clientX,innerWidth-190)}px`;contextMenu.style.top=`${Math.min(clientY,innerHeight-280)}px`;contextMenu.hidden=false}
function meshFromListContext(event){const list=$('meshList'),option=event.target.closest?.('option')||list.options[list.selectedIndex];return option?editableMeshes().find(item=>item.userData.editId===option.value):null}
document.addEventListener('contextmenu',event=>{event.preventDefault();hideContextMenu();if(renderer.domElement.contains(event.target)){const hit=hitAt(event);if(hit&&!selectedMeshes.includes(hit))selectMesh(hit,event.ctrlKey||event.shiftKey);if(!hit&&!selectedMeshes.length)return;showContextMenuAt(event.clientX,event.clientY);return}if($('meshList').contains(event.target)){const item=meshFromListContext(event);if(!item)return;lastMeshListInteractedId=item.userData.editId;if(!selectedMeshes.includes(item))selectMesh(item,event.ctrlKey||event.shiftKey);showContextMenuAt(event.clientX,event.clientY)}});
document.addEventListener('pointerdown',event=>{if(!contextMenu.contains(event.target)&&event.button!==2)hideContextMenu()});
contextMenu.querySelectorAll('[data-context]').forEach(button=>button.onclick=()=>{const action=button.dataset.context;hideContextMenu();if(action==='rigid')setSolidProperty('rigid');if(action==='plastic')setSolidProperty('plastic');if(action==='rename')renameSelectedComponent();if(action==='cut')cutPlasticWithRigid();if(action==='split')splitSelectedDisconnected();if(action==='delete')deleteSelected();if(action==='group')groupSelected();if(action==='ungroup')ungroupSelected();if(action==='copy')copySelected();if(action==='paste')pasteSelected();if(action==='alignX')alignAxisLine('x');if(action==='alignY')alignAxisLine('y');if(action==='alignZ')alignAxisLine('z')});
document.addEventListener('keydown',event=>{const editing=/^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName);if(event.key==='Escape'){hideContextMenu();clearSelection();return}if(editing)return;if(keyboardTransform(event))return;const ctrl=event.ctrlKey||event.metaKey;if(event.altKey&&(event.key==='ArrowLeft'||event.key==='ArrowRight')){event.preventDefault();event.key==='ArrowLeft'?undoOneStep():redoOneStep();return}if(event.repeat&&ctrl&&(event.key.toLowerCase()==='z'||event.key.toLowerCase()==='y')){event.preventDefault();return}if(ctrl&&event.key.toLowerCase()==='c'){event.preventDefault();copySelected()}else if(ctrl&&event.key.toLowerCase()==='v'){event.preventDefault();pasteSelected()}else if(ctrl&&event.key.toLowerCase()==='d'){event.preventDefault();copySelected();pasteSelected()}else if(ctrl&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?$('redoBtn').click():$('undoBtn').click()}else if(ctrl&&event.key.toLowerCase()==='y'){event.preventDefault();$('redoBtn').click()}else if(ctrl&&event.key.toLowerCase()==='a'){event.preventDefault();selectMeshes(editableMeshes())}else if(event.key==='Delete')deleteSelected();else if(event.key.toLowerCase()==='w')document.querySelector('[data-transform="translate"]').click();else if(event.key.toLowerCase()==='e')document.querySelector('[data-transform="rotate"]').click();else if(event.key.toLowerCase()==='r')document.querySelector('[data-transform="scale"]').click();else if(event.key.toLowerCase()==='f')fitCamera(false)});
window.addEventListener('hashchange',()=>{const id=new URLSearchParams(location.hash.slice(1)).get('part');if(id&&id!==activePart?.id)selectPart(id)});
const initial=new URLSearchParams(location.hash.slice(1)).get('part');renderCatalog();selectPart(initial||library[0].id);
for(const id of ['sizeX','sizeY','sizeZ'])$(id).step='0.1';
window.addEventListener('beforeunload',persistLiveBeforeLeave);
refreshSharedLibrary().catch(error=>{renderSharedNotice({unavailable:true,error});});
function selectionUnits(){const units=[],byGroup=new Map();for(const item of selectedMeshes){const key=item.userData.groupId||item.userData.editId;if(!byGroup.has(key)){const unit={items:[],center:new THREE.Vector3(),bounds:new THREE.Box3()};byGroup.set(key,unit);units.push(unit)}byGroup.get(key).items.push(item)}model.updateMatrixWorld(true);for(const unit of units){unit.bounds.makeEmpty();unit.items.forEach(item=>unit.bounds.expandByObject(item,true));unit.bounds.getCenter(unit.center)}return units}
function alignSelected(axis,label){if(selectedMeshes.length<2){$('status').textContent='请至少选择两个构件后再对齐。';return}model.updateWorldMatrix(true,false);const anchorMesh=selectedMesh,units=selectionUnits();if(units.length<2){$('status').textContent='当前选择只有一个组合体，无需对齐。';return}const anchorUnit=units.find(unit=>unit.items.includes(anchorMesh))||units[units.length-1],movingUnits=units.filter(unit=>unit!==anchorUnit);snapshot();
  const anchorCenter=anchorUnit.bounds.getCenter(new THREE.Vector3()),anchorAxis=new THREE.Vector3(axis==='x'?1:0,axis==='y'?1:0,axis==='z'?1:0),worldToModel=model.matrixWorld.clone().invert();
  for(const unit of movingUnits){const current=unit.bounds.getCenter(new THREE.Vector3()),difference=anchorCenter.clone().sub(current),offset=axis==='xyz'?difference:difference.sub(anchorAxis.clone().multiplyScalar(difference.dot(anchorAxis)));if(offset.lengthSq()>1e-12){const originWorld=unit.items[0].getWorldPosition(new THREE.Vector3()),targetLocal=originWorld.clone().add(offset).applyMatrix4(worldToModel),originLocal=originWorld.clone().applyMatrix4(worldToModel),localDelta=targetLocal.sub(originLocal);unit.items.forEach(item=>item.position.add(localDelta))}}
  model.updateWorldMatrix(true,false);const anchorSize=new THREE.Vector3();anchorUnit.bounds.makeEmpty();anchorUnit.items.forEach(item=>anchorUnit.bounds.expandByObject(item,true));anchorUnit.bounds.getSize(anchorSize);const mismatch=new Set();for(const unit of movingUnits){unit.bounds.makeEmpty();unit.items.forEach(item=>unit.bounds.expandByObject(item,true));const size=unit.bounds.getSize(new THREE.Vector3());for(const key of ['x','y','z'])if(Math.abs(size[key]-anchorSize[key])>.0001)mismatch.add(key)}captureCustomScene();const orderedSelection=[...selectedMeshes.filter(item=>item!==anchorMesh),anchorMesh];selectMeshes(orderedSelection);markDirty();const sizeWarning=mismatch.size?` 注意：${[...mismatch].map(key=>key.toUpperCase()).join('、')} 向外沿尺寸不同，中心对齐后边缘不会齐平。`:'';$('status').textContent='已完成 '+(label||String(axis).toUpperCase()+' 全局轴线中心对齐')+'：按全局统一 X/Y/Z 坐标轴线对齐，不改变最后选中构件。'+sizeWarning}
const axisLineCoordinates={x:['y','z'],y:['x','z'],z:['x','y']};
function alignAxisLine(axis){alignSelected(axis,axis.toUpperCase()+' 轴线对齐')}
$('alignX').onclick=()=>alignAxisLine('x');$('alignY').onclick=()=>alignAxisLine('y');$('alignZ').onclick=()=>alignAxisLine('z');$('alignXYZ').onclick=()=>alignSelected('xyz','XYZ 中心重合');
function keyboardTransform(event){if(!selectedMeshes.length||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return false;if(transformFrame==='local'&&selectedMeshes.length!==1){$('status').textContent='工件局部坐标仅支持单选构件；多选操作已忽略。';return false}const mode=transform.mode||'translate',fine=event.ctrlKey?.25:1,step=mode==='translate'?.01*fine:mode==='rotate'?THREE.MathUtils.degToRad(5*fine):.05*fine,sign=event.key==='ArrowLeft'||event.key==='ArrowDown'?-1:1,all=event.ctrlKey&&!event.altKey,axis=event.altKey?'z':event.key==='ArrowLeft'||event.key==='ArrowRight'?'x':'y';const axes=all?['x','y','z']:[axis];if(selectionPivot&&mode==='scale'&&axes.some(current=>selectedMeshes.some(item=>dimensionMode(item,current)==='fixed'))){$('status').textContent='所选组合含固定尺寸构件；已拒绝整组缩放，模型未修改。';return false}snapshot();if(selectionPivot)prepareGroupTransform();const object=selectionPivot||selectedMesh,local=transformFrame==='local'&&selectedMesh?.userData.workFrame&&!selectionPivot,frame=local?activeFrameWorld():{origin:new THREE.Vector3(),quaternion:new THREE.Quaternion()};if(mode==='translate'){for(const current of axes){const delta=new THREE.Vector3(current==='x'?1:0,current==='y'?1:0,current==='z'?1:0).multiplyScalar(sign*step);if(selectionPivot)object.position.add(delta);else if(local){const world=object.getWorldPosition(new THREE.Vector3()).add(delta.applyQuaternion(frame.quaternion));model.updateWorldMatrix(true,false);object.position.copy(model.worldToLocal(world))}else{const semantic=object.position.clone().applyQuaternion(legacyPartToSemantic).add(delta);object.position.copy(semantic.applyQuaternion(legacyPartToSemantic.clone().invert()))}}}else if(mode==='rotate'){let semanticRotation=selectionPivot?object.quaternion.clone():local?object.getWorldQuaternion(new THREE.Quaternion()):legacyPartToSemantic.clone().multiply(object.quaternion).multiply(legacyPartToSemantic.clone().invert());if(local)semanticRotation.premultiply(frame.quaternion.clone().invert()).normalize();const euler=new THREE.Euler().setFromQuaternion(semanticRotation,'XYZ');for(const current of axes)euler[current]+=sign*step;let updated=new THREE.Quaternion().setFromEuler(euler);if(local){updated.premultiply(frame.quaternion).normalize();const parentWorldQ=new THREE.Quaternion().setFromRotationMatrix(model.matrixWorld);object.quaternion.copy(parentWorldQ.invert().multiply(updated).normalize())}else object.quaternion.copy(selectionPivot?updated:legacyPartToSemantic.clone().invert().multiply(updated).multiply(legacyPartToSemantic))}else if(selectionPivot){const factors=[1,1,1];for(const current of axes)factors['xyz'.indexOf(current)]=Math.max(.01,1+sign*step);selectionPivot.updateMatrixWorld(true);const origin=selectionPivot.getWorldPosition(new THREE.Vector3());applyGroupTransformDelta(worldScaleDelta(origin,factors))}else if(selectedMeshes.length===1){captureScaleBaseline();const factors=[1,1,1];for(const current of axes)factors['xyz'.indexOf(current)]=Math.max(.01,1+sign*step);applyWorkFrameScale(factors);workScaleBaseline=null}if(selectionPivot&&mode!=='scale')applyGroupTransformDelta();selectionHelpers.forEach(helper=>helper.update());captureCustomScene();syncTransformFields();markDirty();event.preventDefault();return true}


